package com.shabakaty.cinemana.local;
import android.content.*;import android.database.*;import android.database.sqlite.*;
import java.net.*;import java.io.*;import java.lang.reflect.*;import java.util.*;import java.util.concurrent.*;import org.json.*;
/** Secondary recovery for stale signed media URLs. Never loops a rejected URL or deletes media. */
public final class ExpiredLink269 {
 static final ExecutorService worker=Executors.newSingleThreadExecutor();static final Set<Integer> pending=Collections.newSetFromMap(new ConcurrentHashMap<Integer,Boolean>());
 static long expiry(String url){try{String q=new URI(url).getRawQuery();if(q!=null)for(String pair:q.split("&")){String[] kv=pair.split("=",2);if(kv.length==2&&kv[0].equalsIgnoreCase("Expires"))return Long.parseLong(kv[1]);}}catch(Exception ignored){}return 0;}
 static boolean expired(String url,long now){long time=expiry(url);return time>0&&time<=now/1000+30;}
 static boolean sameMedia(String a,String b){try{URI x=new URI(a),y=new URI(b);return x.getHost()!=null&&x.getHost().equalsIgnoreCase(y.getHost())&&x.getPath().equals(y.getPath());}catch(Exception e){return false;}}
 static boolean safe(String value){try{URI u=new URI(value);String h=u.getHost();return "https".equals(u.getScheme())&&h!=null&&(h.equals("shabakaty.cc")||h.endsWith(".shabakaty.cc")||h.equals("shabakaty.com")||h.endsWith(".shabakaty.com"));}catch(Exception e){return false;}}
 static String resolution(String value){return value==null?"":value.toLowerCase(Locale.ROOT).replace(" ","");}
 static List<String> candidates(JSONArray array,String old,String quality,long now)throws Exception {LinkedHashSet<String> exact=new LinkedHashSet<>(),other=new LinkedHashSet<>();for(int n=0;n<array.length();n++){JSONObject o=array.getJSONObject(n);String url=o.optString("videoUrl");if(!safe(url)||url.equals(old)||expired(url,now))continue;if(sameMedia(old,url))exact.add(url);else if(!quality.isEmpty()&&(resolution(quality).equals(resolution(o.optString("name")))||resolution(quality).equals(resolution(o.optString("resolution")))))other.add(url);}List<String> result=new ArrayList<>(exact);result.addAll(other);return result;}
 static boolean rejected(String message){return message!=null&&message.matches("(?is).*(?:code(?: error)?[:= ]+|HTTP[ /]*)(401|403|404)(?:\\D.*|$)");}
 public static void failed(Context context,Object task,Throwable error){if(context==null||task==null||error==null)return;try{String message=String.valueOf(error.getMessage());if(!rejected(message))return;int id=((Number)task.getClass().getMethod("getId").invoke(task)).intValue();context.getSharedPreferences("link_repair269",0).edit().putBoolean("bad_"+id,true).apply();LocalRuntime.log("link_rejected task="+id);}catch(Exception e){LocalRuntime.failure("link_error_trace",e);}}
 static class Row {String database,id,url,path,title,image,status,quality="";int task;long progress;}
 static Row row(Context c,int task)throws Exception {for(String filename:c.databaseList()){if(filename.endsWith("-wal")||filename.endsWith("-shm")||filename.endsWith("-journal"))continue;SQLiteDatabase db=null;try{db=SQLiteDatabase.openDatabase(c.getDatabasePath(filename).getPath(),null,SQLiteDatabase.OPEN_READONLY);Cursor cursor=db.rawQuery("SELECT * FROM Downloads WHERE task_id=?",new String[]{String.valueOf(task)});try{if(cursor.moveToFirst()){Row r=new Row();r.database=filename;r.task=task;r.id=cursor.getString(cursor.getColumnIndexOrThrow("external_id"));r.url=cursor.getString(cursor.getColumnIndexOrThrow("url"));r.path=cursor.getString(cursor.getColumnIndexOrThrow("path"));r.title=cursor.getString(cursor.getColumnIndexOrThrow("title"));r.image=cursor.getString(cursor.getColumnIndexOrThrow("img"));r.progress=cursor.getLong(cursor.getColumnIndexOrThrow("progress_bytes"));r.status=cursor.getString(cursor.getColumnIndexOrThrow("status"));return r;}}finally{cursor.close();}}catch(SQLiteException ignored){}finally{if(db!=null)db.close();}}return null;}
 static String status(Row row){try{for(Object value:Class.forName("com.shabakaty.downloader.xc4").getEnumConstants())if(String.valueOf(value.getClass().getField("r").getInt(value)).equals(row.status))return ((Enum)value).name();}catch(Exception ignored){}return "UNKNOWN";}
 static boolean allowed(Object manager,int id)throws Exception {Class<?> type=Class.forName("com.shabakaty.cinemana.ca1.Restart108");return (Boolean)type.getMethod("canRetry",Object.class,int.class).invoke(null,manager,id);}
 static boolean running(int task){try{Class<?> type=Class.forName("com.liulishuo.filedownloader.FileDownloadList");Object list=type.getMethod("getImpl").invoke(null);Object running=type.getMethod("get",int.class).invoke(list,task);if(running==null)return false;Object origin=Class.forName("com.liulishuo.filedownloader.BaseDownloadTask$IRunningTask").getMethod("getOrigin").invoke(running);return (Boolean)Class.forName("com.liulishuo.filedownloader.BaseDownloadTask").getMethod("isRunning").invoke(origin);}catch(Exception ignored){return false;}}
 public static boolean beforeRetry(final Object manager,final int task){try{final Context context=(Context)manager.getClass().getField("a").get(manager);Row r=row(context,task);if(r==null||r.id==null||!r.id.matches("[0-9]{1,20}")||r.path==null||!r.path.toLowerCase(Locale.ROOT).endsWith(".mp4"))return false;boolean bad=context.getSharedPreferences("link_repair269",0).getBoolean("bad_"+task,false);if(!expired(r.url,System.currentTimeMillis())&&!bad)return false;if(running(task))return true;String state=status(r);if(!bad&&!Arrays.asList("ERROR","RETRY","WARN").contains(state))return false;if(state.equals("COMPLETED")||state.equals("PAUSED")||!allowed(manager,task))return true;
  SharedPreferences prefs=context.getSharedPreferences("link_repair269",0);long last=prefs.getLong("attempt_"+r.id,0),now=System.currentTimeMillis();if(now-last<300000)return true;int count=prefs.getInt("count_"+r.id,0);long day=prefs.getLong("day_"+r.id,0);if(now-day>86400000){count=0;day=now;}if(count>=3)return true;if(!pending.add(task))return true;prefs.edit().putLong("attempt_"+r.id,now).putLong("day_"+r.id,day).putInt("count_"+r.id,count+1).apply();
  worker.execute(()->{try{recover(context,manager,task);}catch(Exception e){LocalRuntime.failure("link_refresh",e);}finally{pending.remove(task);}});return true;
 }catch(Exception e){LocalRuntime.failure("link_guard",e);return false;}}
 static boolean cancelled(Context context,int task,String id){if(context.getSharedPreferences("ca1_delete_intent",0).getBoolean(id,false)||context.getSharedPreferences("ca1_restart108",0).getString("intent:"+task,"").endsWith("|PAUSE"))return true;try{Method method=Class.forName("com.shabakaty.cinemana.ca1.Queue110").getDeclaredMethod("isPaused",int.class);method.setAccessible(true);return (Boolean)method.invoke(null,task);}catch(Exception ignored){return false;}}
 static void recover(Context c,Object manager,int task)throws Exception {Row original=row(c,task);if(original==null||!original.id.matches("[0-9]{1,20}")||!allowed(manager,task))return;LocalRuntime.log("link_refresh_begin id="+original.id+" expired="+expired(original.url,System.currentTimeMillis()));
  // Changing the signed URL changes the engine task ID. Do not discard an unverified partial file.
  if(original.progress>0||new File(original.path).length()>0||new File(original.path+".temp").length()>0){LocalRuntime.log("link_refresh_wait_partial id="+original.id);return;}
  for(String filename:c.databaseList()){SQLiteDatabase db=null;try{db=SQLiteDatabase.openDatabase(c.getDatabasePath(filename).getPath(),null,SQLiteDatabase.OPEN_READONLY);Cursor cur=db.rawQuery("SELECT qualityName FROM CinemanaDownloadItem WHERE id=? AND downloadTaskId=?",new String[]{original.id,String.valueOf(task)});try{if(cur.moveToFirst())original.quality=cur.isNull(0)?"":cur.getString(0);}finally{cur.close();}}catch(SQLiteException ignored){}finally{if(db!=null)db.close();}}
  JSONArray array=new JSONArray(Metadata269.get("transcoddedFiles/id/"+original.id+"?ca1_refresh="+System.currentTimeMillis(),1024*1024));List<String> options=candidates(array,original.url,original.quality,System.currentTimeMillis());LocalRuntime.log("link_candidates id="+original.id+" count="+options.size());String selected=null;int tested=0;for(String url:options){if(tested++>=3)break;if(probe(url)){selected=url;break;}}if(selected==null){LocalRuntime.log("link_refresh_no_verified_candidate id="+original.id);return;}
  Row current=row(c,task);if(current==null||!current.url.equals(original.url)||current.progress>0||running(task)||!allowed(manager,task))return;
  Method compose=manager.getClass().getMethod("m",String.class,String.class,String.class,String.class,String.class,Integer.class);Object composer=compose.invoke(manager,selected,original.path,original.title,original.image,original.id,null);Object nativeTask=composer.getClass().getField("a").get(composer);int next=((Number)nativeTask.getClass().getMethod("getId").invoke(nativeTask)).intValue();if(next==0||next==task)throw new IOException("task identity did not change");
  SQLiteDatabase database=SQLiteDatabase.openDatabase(c.getDatabasePath(original.database).getPath(),null,SQLiteDatabase.OPEN_READWRITE);try{ContentValues values=new ContentValues();values.put("task_id",next);values.put("url",selected);if(database.update("Downloads",values,"task_id=? AND external_id=? AND url=? AND progress_bytes=0",new String[]{String.valueOf(task),original.id,original.url})!=1)return;}finally{database.close();}
  for(String filename:c.databaseList()){SQLiteDatabase db=null;try{db=SQLiteDatabase.openDatabase(c.getDatabasePath(filename).getPath(),null,SQLiteDatabase.OPEN_READWRITE);ContentValues values=new ContentValues();values.put("downloadTaskId",next);db.update("CinemanaDownloadItem",values,"id=? AND downloadTaskId=?",new String[]{original.id,String.valueOf(task)});}catch(SQLiteException ignored){}finally{if(db!=null)db.close();}}
  if(cancelled(c,task,original.id)||!allowed(manager,next)){LocalRuntime.log("link_refresh_cancelled id="+original.id);return;}manager.getClass().getMethod("q",composer.getClass(),boolean.class).invoke(manager,composer,false);LocalRuntime.log("link_refresh_queued id="+original.id+" old_task="+task+" new_task="+next+" same_media="+sameMedia(original.url,selected));
 }
 static boolean probe(String url){HttpURLConnection c=null;try{c=(HttpURLConnection)new URL(url).openConnection();c.setConnectTimeout(3000);c.setReadTimeout(4000);c.setInstanceFollowRedirects(false);c.setRequestProperty("Range","bytes=0-15");c.setRequestProperty("Accept-Encoding","identity");int code=c.getResponseCode();LocalRuntime.log("link_probe status="+code);if(code!=200&&code!=206)return false;try(InputStream in=c.getInputStream()){byte[] bytes=new byte[12];int read=0,n;while(read<bytes.length&&(n=in.read(bytes,read,bytes.length-read))>0)read+=n;return read>=8&&bytes[4]=='f'&&bytes[5]=='t'&&bytes[6]=='y'&&bytes[7]=='p';}}catch(Exception e){LocalRuntime.failure("link_probe",e);return false;}finally{if(c!=null)c.disconnect();}}
}
